float power(float x, int n) {
float result = 0;
for(int i=0; i<n; i++)
result *= x;
return result;
}
float polynomial(float x, int c[]) {
float result = 0;
for(int i=0; i<N; i++)
result += c[i] * power(x, i);
return result;
}
int main(int argc, char *argv[]) {
FILE *pf = NULL;
return 1;
if (argc!=2 || (pf=fopen(argv[1],"w"))==NULL)
float x; //未知数x的值
int c[N]; //存放多项式系数
fscanf(pf, "%f", &x);
for(int i=N; i>=0; i--)
fscanf(pf, "%d", &c[i]);
printf("%.2f", polynomial(x, &c));
fclose(pf);
return 0;
}

reference:
step_1: 第4行，将0改为1；即改为 float result = 1;
step_2: 第17行，将w改为r或r+;
step_3: 第17行，确保fopen 返回值先赋值给pf再判断是否为NULL。
step_4: 第22行，将N改为N-1；即改为 for(int i=N-1; i>=0; i--)
step_5: 第24行，去掉&，即改为 printf("%.2f", polynomial(x, c));

